INSERT INTO messages(id,folder_id,message_id,subject,from_addr,to_addr_json,cc_addr_json,bcc_addr_json,date,body_text,body_html,is_read,is_important,is_flagged,headers_json,uid,size,created_at) VALUES (240,1,'<msg-tb011-240@example>','[Please review] Reimbursement and Invoicing Guidelines｜June','procure@example.com','["luyao@example.com"]','[]','[]','2026-06-28T14:54:30+08:00','Article 684 [Please Review] Reimbursement and Invoice Guidelines｜June·procure@example.com, the entry states “The payee and contract sign…additional explanation is required before payment”. For procurement-related matters, please contact the Procurement Team. Four non-compliant invoices were returned this week; please conduct a self-check within each team.',NULL,0,1,0,'{}',427,4700,'2026-06-28T14:54:30+08:00');
